function sumCounts(nums) {
  const n = nums.length;
  let total = 0;

  for (let start = 0; start < n; start++) {
    const seen = new Set();
    for (let end = start; end < n; end++) {
      seen.add(nums[end]);
      const distinct = seen.size;
      total += distinct * distinct;
    }
  }
  return total;
}

