function sumCounts(nums) {
  // Cut out every subarray separately and count its different values by sorting a copy.
  let answer = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i; j < nums.length; j++) {
      const piece = nums.slice(i, j + 1).sort((a, b) => a - b);
      let count = 0;
      piece.forEach((value, at) => { if (at === 0 || value !== piece[at - 1]) count++; });
      answer += count ** 2;
    }
  }
  return answer;
}

