function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  // Few distinct values give long repeats; many give mostly distinct subarrays.
  const top = [1, 2, 4, 100][Math.floor(rand() * 4)];
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  return [nums];
}
